import"./modulepreload-polyfill-B5Qt9EMX.js";const s="http://192.168.100.6:8080";async function a(t,o){const e=await fetch(`${s}/usuario/login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:t,password:o})});if(!e.ok)throw new Error("Credenciales incorrectas");return e.json()}const c=document.getElementById("loginForm"),r=document.getElementById("mensaje");c.addEventListener("submit",async t=>{t.preventDefault();const o=document.getElementById("username").value,e=document.getElementById("password").value;try{const n=await a(o,e);console.log("Usuario recibido:",n),localStorage.setItem("auth","true"),window.location.href="../home/home.html"}catch(n){console.error(n),r.textContent="Usuario o contraseña incorrectos ❌",r.style.display="block"}});
